<?php
namespace App\Http\Controllers\Api;use App\Models\DeliveryZone;use Illuminate\Http\Request;class DeliveryZoneController extends Controller{public function index(Request $r){$q=DeliveryZone::query();if($r->search)$q->where('name','like','%'.$r->search.'%');return $this->ok($q->latest()->paginate($r->integer('per_page',15)));}public function store(Request $r){$i=DeliveryZone::create($r->all());return $this->ok($i,'Created');}public function show(DeliveryZone $deliveryZone){return $this->ok($deliveryZone);}public function update(Request $r,DeliveryZone $deliveryZone){$deliveryZone->update($r->all());return $this->ok($deliveryZone,'Updated');}public function destroy(DeliveryZone $deliveryZone){$deliveryZone->delete();return $this->ok(null,'Deleted');}}
